function humanDuration(t,e){return!e||t<0?"n/a":t<60?t+"s":t<3600?Math.round(t/60)+"m":(t/3600).toFixed(1)+"h"}function renderFunnel(t){var e="";return $.each(t||[],(function(t,r){var a;a=r.measured?"<strong>"+escapeHtml(String(r.targets))+"</strong>":'<span class="text-muted">Not measured</span>';var n="";$.each(r.techniques||[],(function(t,e){n+="<code>"+escapeHtml(e)+"</code> "})),e+="<tr><td>"+escapeHtml(r.stage)+"</td><td>"+n+'</td><td class="text-right">'+a+"</td></tr>"})),'<h4>Kill Chain</h4><table class="table table-condensed table-hover"><thead><tr><th>Stage</th><th>ATT&amp;CK</th><th class="text-right">Targets</th></tr></thead><tbody>'+e+"</tbody></table>"}function renderFrictionScope(t){return t?'<p class="text-muted"><small>'+escapeHtml(t)+"</small></p>":""}function renderFriction(t,e){if(!t||0===t.length)return"<h4>Defensive Friction</h4>"+renderFrictionScope(e)+'<p class="text-muted">No cloaker enforcement recorded.</p>';var r="";return $.each(t,(function(t,e){r+="<tr><td>"+escapeHtml(e.organization||"unknown")+"</td><td>"+escapeHtml(e.asn||"")+'</td><td class="text-right">'+escapeHtml(String(e.count))+"</td></tr>"})),"<h4>Defensive Friction</h4>"+renderFrictionScope(e)+'<table class="table table-condensed table-hover"><thead><tr><th>Organization</th><th>ASN</th><th class="text-right">Blocked</th></tr></thead><tbody>'+r+"</tbody></table>"}function renderRace(t){return t=t||{},'<h4>Report vs. Capture</h4><table class="table table-condensed"><tr><td>Delivered</td><td class="text-right">'+escapeHtml(String(t.delivered||0))+'</td></tr><tr><td>Reported before capture</td><td class="text-right"><strong>'+escapeHtml(String(t.reported_before_capture||0))+'</strong></td></tr><tr><td>Reported after capture</td><td class="text-right">'+escapeHtml(String(t.reported_after_capture||0))+'</td></tr><tr><td>Never reported</td><td class="text-right">'+escapeHtml(String(t.never_reported||0))+'</td></tr><tr><td>Median time to report</td><td class="text-right">'+escapeHtml(humanDuration(t.median_time_to_report_seconds,t.has_median_time_to_report))+"</td></tr></table>"}function renderNavigatorLink(){return'<button type="button" id="resilience-navigator-download" class="btn btn-default btn-sm"><i class="fa fa-download"></i> Download ATT&amp;CK Navigator layer</button>'}function downloadNavigatorLayer(t){api.campaignId.resilienceNavigator(t).success((function(t){var e=JSON.stringify(t,null,2),r=new Blob([e],{type:"application/json;charset=utf-8;"}),a="olta-navigator-layer.json";if(navigator.msSaveBlob)navigator.msSaveBlob(r,a);else{var n=window.URL.createObjectURL(r),o=document.createElement("a");o.href=n,o.setAttribute("download",a),document.body.appendChild(o),o.click(),document.body.removeChild(o),window.URL.revokeObjectURL(n)}})).error((function(){errorFlash(" Could not download the ATT&CK Navigator layer.")}))}function loadResilience(t){api.campaignId.resilience(t).success((function(e){e=e||{},$("#resilience-panel").html(renderFunnel(e.funnel)+renderFriction(e.friction,e.friction_scope)+renderRace(e.race)+renderNavigatorLink()),$("#resilience-navigator-download").on("click",(function(){downloadNavigatorLayer(t)}))})).error((function(){$("#resilience-panel").html('<div class="alert alert-danger">Could not load the resilience report.</div>')}))}